      // clear  harp-roll-01       (the board is cleared)
      // burn   error-warm-layered-01             (the lava eats a ball)
      // line   whoosh-whistle-ascending-01  (a row / column clear)
      // steel  click-metallic-01             (the ball rings off steel)
      // swap   click-toggle-01                      (the tap: the buttons switch)
      // big    powerup-04                          (the ball grows)
      // fire   loop-thruster-02                    (the ball catches fire)
      // magnet forcefield-02                       (the ball turns into a magnet)
      "shoot": "data:audio/mpeg;base64,",
      "brick": "data:audio/mpeg;base64,",
      "wall": "data:audio/mpeg;base64,",
      "tick": "data:audio/mpeg;base64,",
      "chain": "data:audio/mpeg;base64,",
      "gold": "data:audio/mpeg;base64,",
      "blast": "data:audio/mpeg;base64,",
      "drop": "data:audio/mpeg;base64,",
      "clear": "data:audio/mpeg;base64,",
      "burn": "data:audio/mpeg;base64,",
